class Solution {
public:
    int findComplement(int num) {
        long long mask = 1;
        while (mask < num) {
            mask = (mask << 1) | 1;
        }
        return num ^ (int)mask;
    }
};

class Solution {
    public int findComplement(int num) {
        long mask = 1;
        while (mask < num) {
            mask = (mask << 1) | 1;
        }
        return num ^ (int)mask;
    }
}

var findComplement = function(num) {
    let mask = 1;
    while (mask < num) {
        mask = (mask << 1) | 1;
    }
    return num ^ mask;
};
